function ensureRemoteBranch(branchName) {
  if (!branchName) {
    return false;
  }

  if (gitOk(["rev-parse", "--verify", `refs/remotes/origin/${branchName}`])) {
    return true;
  }

  try {
    git([
      "fetch",
      "--no-tags",
      "--depth=1",
      "origin",
      `+refs/heads/${branchName}:refs/remotes/origin/${branchName}`,
    ]);
    return true;
  } catch {
    return false;
  }
}

