        },
        ...(input.value !== undefined ? { value: input.value } : {}),
        ...(input.key !== undefined ? { key: input.key } : {}),
      },
      eventPaths: sinkPaths,
    }),
  );

  await scope.sessionManager.markRunning(session.sessionId, {
