export async function serveMcpServer(options: ServeMcpServerOptions): Promise<void> {
  const runtime = new ProbefnRuntime(options.repoRoot);
  const server = new ProbefnMcpServer(runtime);
  const toolNames = server.listTools().map((tool) => tool.name);

  if (options.transport === 'stdio') {
    process.stderr.write(`probefn mcp stdio ready: ${toolNames.join(', ')}\n`);
    const transport = createStreamTransport(process.stdin, process.stdout);
    await server.serveTransport(transport, options.signal);
    return;
  }

  const port = options.tcpPort ?? 7007;
  const netServer = await new Promise<NetServer>((resolve, reject) => {
    const listeningServer = createServer((socket) => {
      const transport = createStreamTransport(socket, socket);
      void server.serveTransport(transport, options.signal);
    });
    listeningServer.once('error', reject);
    listeningServer.listen(port, '127.0.0.1', () => resolve(listeningServer));
  });
  const address = netServer.address() as AddressInfo;
  process.stderr.write(
    `probefn mcp tcp ready on 127.0.0.1:${address.port}: ${toolNames.join(', ')}\n`,
  );

  await new Promise<void>((resolve) => {
    const cleanup = () => {
      netServer.close(() => resolve());
    };
    if (options.signal) {
      options.signal.addEventListener('abort', cleanup, { once: true });
    }
  });
}

export class ProbefnMcpServer {
  private readonly runtime: ProbefnRuntime;
  private readonly tools: ToolDefinition[];

  public constructor(runtime: ProbefnRuntime) {
    this.runtime = runtime;
    this.tools = runtime.listTools();
  }

  public listTools(): ToolDefinition[] {
    return [...this.tools];
  }

  public async serveTransport(
    transport: FramedTransport,
    signal?: AbortSignal,
  ): Promise<void> {
    transport.onMessage(async (request) => {
      const response = await this.handleRequest(request);
      if (response) {
        await transport.send(response);
      }
    });

    await new Promise<void>((resolve) => {
      const cleanup = () => {
        transport.close();
        resolve();
      };
      if (signal) {
        signal.addEventListener('abort', cleanup, { once: true });
      }
    });
  }

  public async handleRequest(request: JsonRpcRequest): Promise<JsonRpcResponse | null> {
    if (request.method === 'notifications/initialized') {
      return null;
    }

    if (request.method === 'initialize') {
      return {
        jsonrpc: '2.0',
        id: request.id ?? null,
        result: {
          protocolVersion:
            typeof request.params?.protocolVersion === 'string'
              ? request.params.protocolVersion
              : DEFAULT_PROTOCOL_VERSION,
          capabilities: {
            tools: {},
          },
          serverInfo: {
            name: 'probefn',
            version: SERVER_VERSION,
          },
        },
      };
    }

    if (request.method === 'ping') {
      return {
        jsonrpc: '2.0',
        id: request.id ?? null,
        result: {},
      };
    }

    if (request.method === 'tools/list') {
      return {
        jsonrpc: '2.0',
        id: request.id ?? null,
        result: {
          tools: this.tools.map((tool) => ({
            name: tool.name,
            description: tool.description,
            inputSchema: tool.inputSchema,
          })),
        },
      };
    }

    if (request.method === 'tools/call') {
      const toolName = typeof request.params?.name === 'string' ? request.params.name : null;
      if (!toolName) {
        return {
          jsonrpc: '2.0',
          id: request.id ?? null,
          error: {
            code: -32602,
            message: 'Missing required field name.',
          },
        };
      }

      const toolResult = await this.runtime.callTool(
        toolName,
        request.params?.arguments,
      );
      return {
        jsonrpc: '2.0',
        id: request.id ?? null,
        result: toolResult as unknown as JsonObject,
      };
    }

    return {
      jsonrpc: '2.0',
      id: request.id ?? null,
      error: {
        code: -32601,
        message: `Method ${request.method} is not supported.`,
      },
    };
  }
