    const sent: Array<Parameters<MailFnSendAdapter['send']>[0]> = [];
    const sendAdapter: MailFnSendAdapter = {
      async send(request) { sent.push(request); return { providerMessageId: `sent-${sent.length}`, status: 'queued' }; },
    };
    const context = await setup({ sendAdapter });
    const created = await createInbox(context);
    const value = raw({ internetMessageId: '<origin@example.com>', references: ['<root@example.com>'], subject: 'Question' });
