      }
    },

    async scheduled(_event: unknown, env: MailFnCloudflareEnv, ctx: ExecutionContext): Promise<void> {
      const mailfn = await createCloudflareMailFn(env, options);
      ctx.waitUntil(mailfn.runRetention(env.MAILFN_PROJECT_ID));
    },
  };
