export function createMailFnHttpHandler(config: MailFnHttpHandlerConfig): (request: Request) => Promise<Response> {
  const route = createMailFnRouteHandler(config);
  return async (request) => cors(await route(request), request, config.corsOrigins);
}

function createMailFnRouteHandler(config: MailFnHttpHandlerConfig): (request: Request) => Promise<Response> {
  return async (request) => {
    const requestId = request.headers.get('x-request-id') ?? `req_${crypto.randomUUID().replaceAll('-', '')}`;
    try {
      if (request.method === 'OPTIONS') return cors(new Response(null, { status: 204 }), request, config.corsOrigins);
      const url = new URL(request.url);
      const path = url.pathname.replace(/\/+$/, '') || '/';
      if (path === '/health' && request.method === 'GET') return json({ status: 'ok', version: MAILFN_API_VERSION }, requestId);
      if (path === '/v1/admin/projects' && request.method === 'POST') {
        requireAdmin(request, config.adminToken);
        return json(await config.mailfn.bootstrapProject(await body<CreateProjectInput>(request)), requestId, 201);
      }
      const actor = await authenticate(request, config);

      if (path === '/v1/inboxes' && request.method === 'POST') {
        const input = await body<Omit<CreateInboxInput, 'projectId'>>(request);
