  listMessages(projectId: string, inboxId: string, filter?: MessageFilter): Promise<Message[]>;
  searchMessages(projectId: string, inboxId: string, input: Omit<SearchMessagesInput, 'projectId' | 'inboxId'>): Promise<Message[]>;
