describe('MailFn MCP server', () => {
  it('advertises narrow tools and redacts message content by default', async () => {
    const client = {
      readMessage: vi.fn(async () => message),
      listMessages: vi.fn(async () => ({ items: [message] })),
    } as unknown as MailFnClient;
