import type { MailFnSendAdapter, SendRequest, SendResult } from '@mailfn/core';

export interface SendFnCompatible {
  sendEmail?(input: {
    idempotencyKey: string;
    from: string;
    to: string[];
    cc?: string[];
    bcc?: string[];
    subject: string;
    text?: string;
    html?: string;
    headers?: Record<string, string>;
    attachmentIds?: string[];
    metadata?: Record<string, string>;
  }): Promise<{ id?: string; providerMessageId?: string; status?: string }>;
  email?(input: {
    idempotencyKey?: string;
    userId: string;
    to: string | string[];
    cc?: string | string[];
    bcc?: string | string[];
    subject?: string;
    text?: string;
    html?: string;
    metadata?: Record<string, unknown>;
  }): Promise<{ id?: string; providerMessageId?: string; status?: string }>;
}

export interface SendFnAdapterOptions {
  userId?: (request: SendRequest) => string;
}

export function createSendFnAdapter(sendfn: SendFnCompatible, options: SendFnAdapterOptions = {}): MailFnSendAdapter {
  return {
    async send(request): Promise<SendResult> {
      let result: { id?: string; providerMessageId?: string; status?: string };
      if (sendfn.sendEmail) {
        result = await sendfn.sendEmail({
            idempotencyKey: request.idempotencyKey,
            from: request.from,
            to: request.to,
            cc: request.cc.length ? request.cc : undefined,
            bcc: request.bcc.length ? request.bcc : undefined,
            subject: request.subject,
            text: request.text,
            html: request.html,
            headers: request.headers,
            attachmentIds: request.attachmentIds,
            metadata: request.metadata,
          });
      } else if (sendfn.email) {
        result = await sendfn.email({
              idempotencyKey: request.idempotencyKey,
              userId: options.userId?.(request) ?? request.projectId,
              to: request.to,
              cc: request.cc.length ? request.cc : undefined,
              bcc: request.bcc.length ? request.bcc : undefined,
              subject: request.subject,
              text: request.text,
              html: request.html,
              metadata: {
                ...request.metadata,
                mailfnInboxId: request.inboxId,
                mailfnFrom: request.from,
                mailfnHeaders: request.headers,
                mailfnAttachmentIds: request.attachmentIds,
                mailfnIdempotencyKey: request.idempotencyKey,
              },
            });
      } else {
        throw new Error('SENDFN_SEND_METHOD_UNAVAILABLE');
      }
      const providerMessageId = result.providerMessageId ?? result.id;
      if (!providerMessageId) throw new Error('SENDFN_PROVIDER_MESSAGE_ID_MISSING');
      return {
        providerMessageId,
        status: result.status === 'sent' || result.status === 'delivered' ? 'sent' : 'queued',
      };
    },
  };
}
import { describe, expect, it, vi } from 'vitest';

import { createSendFnAdapter } from './index.js';

const request = {
  idempotencyKey: 'mailfn:draft:d',
  projectId: 'p', inboxId: 'i', from: 'agent@example.com', to: ['recipient@example.com'], cc: [], bcc: [],
  subject: 'Re: Test', text: 'Reply', headers: { 'In-Reply-To': '<m@example.com>' }, attachmentIds: ['a'], metadata: { draftId: 'd' },
};

describe('SendFn composition', () => {
  it('uses the modern delivery contract without duplicating providers', async () => {
    const sendEmail = vi.fn(async () => ({ providerMessageId: 'provider-1', status: 'sent' }));
    await expect(createSendFnAdapter({ sendEmail }).send(request)).resolves.toEqual({ providerMessageId: 'provider-1', status: 'sent' });
    expect(sendEmail).toHaveBeenCalledWith(expect.objectContaining({ idempotencyKey: request.idempotencyKey, from: request.from, headers: request.headers, attachmentIds: ['a'] }));
  });

  it('preserves MailFn correlation and threading metadata on the legacy SendFn surface', async () => {
    const email = vi.fn(async () => ({ id: 'tx-1', status: 'pending' }));
    await expect(createSendFnAdapter({ email }).send(request)).resolves.toEqual({ providerMessageId: 'tx-1', status: 'queued' });
    expect(email).toHaveBeenCalledWith(expect.objectContaining({
      idempotencyKey: request.idempotencyKey,
      userId: 'p', metadata: expect.objectContaining({ mailfnInboxId: 'i', mailfnHeaders: request.headers, mailfnAttachmentIds: ['a'], mailfnIdempotencyKey: request.idempotencyKey }),
    }));
  });
});

