#!/usr/bin/env node
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

const root = process.cwd();
const packageDirs = [
  'mailfn/core',
  'mailfn/client',
  'mailfn/cloudflare',
  'mailfn/testing',
  'mailfn/cli',
  'mailfn/mcp',
  'mailfn/sendfn',
  'mailfn/facade',
];

function run(file, args, cwd = root) {
  execFileSync(file, args, { cwd, stdio: 'inherit', env: { ...process.env, npm_config_audit: 'false', npm_config_fund: 'false' } });
}

for (const directory of packageDirs) {
  const manifest = JSON.parse(readFileSync(path.join(root, directory, 'package.json'), 'utf8'));
  if (!manifest.publishConfig || manifest.publishConfig.access !== 'public') {
    throw new Error(`${directory} is missing public publish metadata`);
  }
  run('npm', ['run', 'clean'], path.join(root, directory));
  run('npm', ['run', 'build'], path.join(root, directory));
  run('npm', ['test'], path.join(root, directory));
}

const mcpProbe = spawnSync(process.execPath, [path.join(root, 'mailfn/mcp/dist/cli.js')], {
  cwd: root,
  encoding: 'utf8',
  input: `${JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: '2025-11-25', capabilities: {}, clientInfo: { name: 'mailfn-gate', version: '1' } } })}\n${JSON.stringify({ jsonrpc: '2.0', id: 2, method: 'tools/list', params: {} })}\n`,
  env: { ...process.env, MAILFN_URL: 'https://mailfn.invalid', MAILFN_TOKEN: 'gate-token' },
});
if (mcpProbe.status !== 0) throw new Error(`MailFn MCP executable probe failed: ${mcpProbe.stderr}`);
const mcpResponses = mcpProbe.stdout.trim().split('\n').map((line) => JSON.parse(line));
if (mcpResponses.length !== 2 || mcpResponses[0]?.result?.protocolVersion !== '2025-11-25' || !Array.isArray(mcpResponses[1]?.result?.tools)) {
  throw new Error(`MailFn MCP executable emitted an invalid stdio exchange: ${mcpProbe.stdout}`);
}

const staging = mkdtempSync(path.join(tmpdir(), 'mailfn-release-'));
try {
  const tarballs = [];
  for (const directory of packageDirs) {
    const output = execFileSync('npm', ['pack', '--json'], { cwd: path.join(root, directory), encoding: 'utf8' });
    const packed = JSON.parse(output);
    tarballs.push(path.join(root, directory, packed[0].filename));
  }
  run('npm', ['init', '-y'], staging);
  run('npm', ['install', '--ignore-scripts', '--package-lock=false', ...tarballs], staging);
  run(process.execPath, ['--input-type=module', '-e', "await import('mailfn'); await import('@mailfn/core'); await import('@mailfn/client'); await import('@mailfn/cloudflare'); await import('@mailfn/testing'); await import('@mailfn/cli'); await import('@mailfn/mcp'); await import('@mailfn/sendfn');"], staging);
  console.log('MailFn release gate passed');
} finally {
  rmSync(staging, { recursive: true, force: true });
  for (const directory of packageDirs) {
    const manifest = JSON.parse(readFileSync(path.join(root, directory, 'package.json'), 'utf8'));
    rmSync(path.join(root, directory, `${manifest.name.replace('@', '').replace('/', '-')}-${manifest.version}.tgz`), { force: true });
  }
}
import type { MailFnObjectStore } from '@mailfn/core';

import type { R2Bucket } from './bindings.js';

export class R2MailFnObjectStore implements MailFnObjectStore {
  public constructor(private readonly bucket: R2Bucket) {}

  public async put(key: string, data: Uint8Array, options?: { contentType?: string; metadata?: Record<string, string> }): Promise<void> {
    await this.bucket.put(key, Uint8Array.from(data), {
      httpMetadata: { contentType: options?.contentType },
      customMetadata: options?.metadata,
    });
  }

  public async get(key: string): Promise<Uint8Array | null> {
    const object = await this.bucket.get(key);
    return object ? new Uint8Array(await object.arrayBuffer()) : null;
  }

  public delete(key: string): Promise<void> {
    return this.bucket.delete(key);
  }
}
import type { MailFnQueue, ParseJob } from '@mailfn/core';

import type { Queue } from './bindings.js';

export class CloudflareMailFnQueue implements MailFnQueue {
  public constructor(private readonly queue: Queue<ParseJob>) {}

  public enqueue(job: ParseJob): Promise<void> {
    return this.queue.send(job, { contentType: 'json' });
  }
}

