import { describe, expect, it } from 'vitest';

import { PostalMimeParser } from './mime.js';

describe('PostalMimeParser', () => {
  it('parses text, HTML, encodings, threading, authentication, and attachments', async () => {
    const raw = [
      'From: Sender <sender@example.com>',
      'To: Target <target@inbound.example.com>',
      'Subject: =?UTF-8?Q?Verify_=E2=9C=93?=',
      'Message-ID: <message@example.com>',
      'In-Reply-To: <parent@example.com>',
      'References: <root@example.com> <parent@example.com>',
      'Authentication-Results: mx.example; spf=pass; dkim=pass; dmarc=pass',
      'MIME-Version: 1.0',
      'Content-Type: multipart/mixed; boundary="outer"',
      '',
      '--outer',
      'Content-Type: multipart/alternative; boundary="inner"',
      '',
      '--inner',
      'Content-Type: text/plain; charset=utf-8',
      'Content-Transfer-Encoding: quoted-printable',
      '',
      'Your code is 123456',
      '--inner',
      'Content-Type: text/html; charset=utf-8',
      '',
      '<p>Your code is <strong>123456</strong></p>',
      '--inner--',
      '--outer',
      'Content-Type: text/plain; name="proof.txt"',
      'Content-Disposition: attachment; filename="proof.txt"',
      'Content-Transfer-Encoding: base64',
      '',
      'ZXZpZGVuY2U=',
      '--outer--',
      '',
    ].join('\r\n');
    const parsed = await new PostalMimeParser().parse(new TextEncoder().encode(raw));
    expect(parsed.subject).toBe('Verify ✓');
    expect(parsed.from).toEqual([{ address: 'sender@example.com', name: 'Sender' }]);
    expect(parsed.inReplyTo).toBe('<parent@example.com>');
    expect(parsed.references).toEqual(['<root@example.com>', '<parent@example.com>']);
    expect(parsed.authenticationResults).toMatchObject({ spf: 'pass', dkim: 'pass', dmarc: 'pass' });
    expect(parsed.text).toContain('123456');
    expect(parsed.html).toContain('<strong>123456</strong>');
    expect(parsed.attachments).toHaveLength(1);
    expect(new TextDecoder().decode(parsed.attachments[0]!.content)).toBe('evidence');
  });

  it('keeps malformed input deterministic instead of executing remote content', async () => {
    const parsed = await new PostalMimeParser().parse(new TextEncoder().encode('Subject: broken\r\n\r\nbody'));
    expect(parsed.subject).toBe('broken');
    expect(parsed.text).toContain('body');
    expect(parsed.attachments).toEqual([]);
  });
});
import type { MailAddress, MailFnMimeParser, ParsedMessage } from '@mailfn/core';
import PostalMime from 'postal-mime';

interface PostalAddress {
  address?: string;
  name?: string;
  group?: PostalAddress[];
}

interface PostalResult {
  messageId?: string;
  subject?: string;
  text?: string;
  html?: string;
  from?: PostalAddress;
  to?: PostalAddress[];
  cc?: PostalAddress[];
  bcc?: PostalAddress[];
  replyTo?: PostalAddress[];
  inReplyTo?: string;
  references?: string | string[];
  headers?: Array<{ key: string; value: string }>;
  attachments?: Array<{
    filename?: string;
    mimeType?: string;
    content?: Uint8Array | ArrayBuffer | string;
    contentId?: string;
    disposition?: string;
  }>;
}

export class PostalMimeParser implements MailFnMimeParser {
  public async parse(raw: Uint8Array): Promise<ParsedMessage> {
    const parsed = (await PostalMime.parse(Uint8Array.from(raw))) as PostalResult;
    const headers: Record<string, string[]> = {};
    for (const header of parsed.headers ?? []) {
      const key = header.key.toLowerCase();
      (headers[key] ??= []).push(header.value);
    }
    const authenticationRaw = headers['authentication-results']?.join('; ');
    return {
      internetMessageId: parsed.messageId ?? first(headers, 'message-id'),
      from: flatten(parsed.from ? [parsed.from] : []),
      to: flatten(parsed.to ?? []),
      cc: flatten(parsed.cc ?? []),
      bcc: flatten(parsed.bcc ?? []),
      replyTo: flatten(parsed.replyTo ?? []),
      subject: parsed.subject,
      text: parsed.text,
      html: parsed.html,
      headers,
      inReplyTo: parsed.inReplyTo ?? first(headers, 'in-reply-to'),
      references: normalizeReferences(parsed.references ?? first(headers, 'references')),
      authenticationResults: authenticationRaw
        ? {
            raw: authenticationRaw,
            spf: result(authenticationRaw, 'spf'),
            dkim: result(authenticationRaw, 'dkim'),
            dmarc: result(authenticationRaw, 'dmarc'),
            arc: result(authenticationRaw, 'arc'),
          }
        : undefined,
      attachments: (parsed.attachments ?? []).map((attachment) => ({
        filename: attachment.filename,
        contentType: attachment.mimeType,
        content: bytes(attachment.content),
        contentId: attachment.contentId,
        disposition: attachment.disposition,
      })),
    };
  }
}

function flatten(entries: PostalAddress[]): MailAddress[] {
  return entries.flatMap((entry) =>
    entry.group?.length
      ? flatten(entry.group)
      : entry.address
        ? [{ address: entry.address, name: entry.name }]
        : [],
  );
}

function first(headers: Record<string, string[]>, key: string): string | undefined {
  return headers[key]?.[0];
}

function normalizeReferences(value: string | string[] | undefined): string[] {
  if (!value) return [];
  const joined = Array.isArray(value) ? value.join(' ') : value;
  return Array.from(joined.matchAll(/<[^>]+>/g), (match) => match[0]);
}

function result(value: string, mechanism: string): string | undefined {
  return new RegExp(`(?:^|[;\\s])${mechanism}=([a-z_-]+)`, 'i').exec(value)?.[1]?.toLowerCase();
}

function bytes(value: Uint8Array | ArrayBuffer | string | undefined): Uint8Array {
  if (value instanceof Uint8Array) return Uint8Array.from(value);
  if (value instanceof ArrayBuffer) return new Uint8Array(value);
  if (typeof value === 'string') return new TextEncoder().encode(value);
  return new Uint8Array();
}

