    this.store.set(model, [...records]);
  }

  protected getTable(model: string): any[] {
    const table = this.store.get(model);
    if (table) {
      return table;
    }

    const nextTable: any[] = [];
    this.store.set(model, nextTable);
    return nextTable;
  }

