    return where.every((clause) => {
      const value = item[clause.field];

      switch (clause.operator) {
        case 'eq':
          return value === clause.value;
        case 'ne':
          return value !== clause.value;
        case 'lt':
          return value < clause.value;
        case 'lte':
          return value <= clause.value;
        case 'gt':
          return value > clause.value;
        case 'gte':
          return value >= clause.value;
        case 'in':
          return Array.isArray(clause.value) && clause.value.includes(value);
        default:
          return false;
      }
    });
  }

