    const admin = await mailfn.authenticate(bootstrap.credential.token);
    const input = {
      projectId: bootstrap.project.id,
      kind: 'expiring' as const,
      requestedLocalPart: 'atomic',
      expirySeconds: 3_600,
      idempotencyKey: 'workerd:atomic',
