    await expect(client.searchMessages('inb_1', { query: 'needle' })).resolves.toEqual({ items: [] });
    await expect(client.createForwardDraft('inb_1', 'msg_1', { to: ['next@example.com'] })).resolves.toMatchObject({ id: 'draft_1' });
