      `SELECT
        SUM(CASE WHEN project_id = ? THEN 1 ELSE 0 END) AS project_count,
        SUM(CASE WHEN project_id = ? AND inbox_id = ? THEN 1 ELSE 0 END) AS inbox_count,
        SUM(CASE WHEN project_id = ? AND sender = ? THEN 1 ELSE 0 END) AS sender_count
