  async sendEmail(request: any): Promise<any> {
    this.sendCalls += 1;
    this.requests.push(request);
    if (this.handler) return this.handler(request);
    return (
      this.responses.shift() || {
        success: true,
        providerMessageId: 'msg-1',
        timestamp: new Date('2026-01-01T00:00:00Z'),
      }
    );
  }
}

