        to: 'user@example.com',
        subject: 'Hello',
        html: '<p>Hello</p>',
      })
    ).rejects.toMatchObject({
      code: 'SENDFN_SUPPRESSED',
      message: 'Recipient is suppressed',
    });

    expect(provider.sendCalls).toBe(0);
  });

