import type { MailDomain, MailFnDomainAdapter } from '@mailfn/core';

export interface CloudflareDomainAdapterConfig {
  apiToken: string;
  zoneId: string;
  /** Exact Cloudflare zone name authorized for this adapter. */
  zoneName: string;
  workerName: string;
  fetch?: typeof globalThis.fetch;
}

interface CloudflareResponse<T> {
  success: boolean;
  result: T;
  errors?: Array<{ code: number; message: string }>;
}

export class CloudflareDomainAdapter implements MailFnDomainAdapter {
  private readonly fetcher: typeof globalThis.fetch;

  public constructor(private readonly config: CloudflareDomainAdapterConfig) {
    this.fetcher = config.fetch ?? globalThis.fetch;
  }

  public async createRouting(domain: MailDomain): Promise<{ routingRuleId: string }> {
    this.assertZone(domain);
    await this.ensureEmailRouting();
    const name = `MailFn ${domain.domain}`;
    const existing = await this.call<Array<{
      id: string;
      name?: string;
      enabled?: boolean;
      matchers?: Array<{ type?: string; field?: string }>;
      actions?: Array<{ type?: string; value?: string[] }>;
    }>>(
      `/zones/${this.config.zoneId}/email/routing/rules`,
      { method: 'GET' },
    );
    const existingRule = existing.find((rule) => rule.name === name);
    if (existingRule) {
      const owned = existingRule.enabled !== false &&
        existingRule.matchers?.some((matcher) => matcher.type === 'all' && matcher.field === 'to') &&
        existingRule.actions?.some((action) => action.type === 'worker' && action.value?.includes(this.config.workerName));
      if (!owned) throw new Error(`MAILFN_CLOUDFLARE_RULE_CONFLICT:${existingRule.id}`);
      return { routingRuleId: existingRule.id };
    }
    const response = await this.call<{ id: string }>(`/zones/${this.config.zoneId}/email/routing/rules`, {
      method: 'POST',
      body: JSON.stringify({
        name,
        enabled: true,
        priority: 0,
        matchers: [{ type: 'all', field: 'to' }],
        actions: [{ type: 'worker', value: [this.config.workerName] }],
      }),
    });
    return { routingRuleId: response.id };
  }

  public async verifyDns(domain: MailDomain): Promise<{ verified: boolean; diagnostics: string[] }> {
    this.assertZone(domain);
    await this.call(`/zones/${this.config.zoneId}/email/routing/dns`, { method: 'GET' });
    const diagnostics: string[] = [];
    for (const expected of domain.expectedRecords) {
      const query = new URLSearchParams({ type: expected.type, name: expected.name });
      const records = await this.call<Array<{ type: string; name: string; content: string; priority?: number }>>(
        `/zones/${this.config.zoneId}/dns_records?${query}`,
        { method: 'GET' },
      );
      const match = records.some(
        (record) =>
          record.type === expected.type &&
          record.name.replace(/\.$/, '') === expected.name.replace(/\.$/, '') &&
          record.content.replace(/\.$/, '') === expected.value.replace(/\.$/, '') &&
          (expected.priority === undefined || record.priority === expected.priority),
      );
      if (!match) diagnostics.push(`Missing ${expected.type} ${expected.name}`);
    }
    return { verified: diagnostics.length === 0, diagnostics };
  }

  public async disableRouting(domain: MailDomain): Promise<void> {
    this.assertZone(domain);
    if (!domain.routingRuleId) return;
    await this.call(`/zones/${this.config.zoneId}/email/routing/rules/${domain.routingRuleId}`, { method: 'DELETE' });
  }

  private assertZone(domain: MailDomain): void {
    const zoneName = this.config.zoneName.trim().toLowerCase().replace(/\.$/, '');
    if (domain.domain !== zoneName) {
      throw new Error(`MAILFN_CLOUDFLARE_ZONE_MISMATCH:${domain.domain}`);
    }
  }

  private async ensureEmailRouting(): Promise<void> {
    const status = await this.call<{ enabled?: boolean; status?: string }>(
      `/zones/${this.config.zoneId}/email/routing`,
      { method: 'GET' },
    );
    if (status.enabled || status.status === 'enabled' || status.status === 'ready') return;
    await this.call(`/zones/${this.config.zoneId}/email/routing/enable`, { method: 'POST' });
  }

  private async call<T = unknown>(path: string, init: RequestInit): Promise<T> {
    const response = await this.fetcher(`https://api.cloudflare.com/client/v4${path}`, {
      ...init,
      headers: {
        Authorization: `Bearer ${this.config.apiToken}`,
        'Content-Type': 'application/json',
        ...init.headers,
      },
    });
    const body = (await response.json()) as CloudflareResponse<T>;
    if (!response.ok || !body.success) {
      throw new Error(`MAILFN_CLOUDFLARE_API_FAILED:${body.errors?.map((error) => error.code).join(',') ?? response.status}`);
    }
    return body.result;
  }
}
import { describe, expect, it, vi } from 'vitest';

import type { MailDomain } from '@mailfn/core';

import { CloudflareDomainAdapter } from './domain.js';

const domain = {
  id: 'dom_1', projectId: 'prj_1', domain: 'mail.example.com', status: 'pending', verificationToken: 'token',
  expectedRecords: [
    { type: 'TXT', name: '_mailfn.mail.example.com', value: 'mailfn-verification=token' },
    { type: 'MX', name: 'mail.example.com', value: 'route1.mx.cloudflare.net' },
  ],
  createdAt: '2026-08-10T00:00:00.000Z', updatedAt: '2026-08-10T00:00:00.000Z',
} satisfies MailDomain;

describe('CloudflareDomainAdapter', () => {
  it('verifies exact DNS evidence and creates a reversible Worker routing rule', async () => {
    const requests: Array<{ url: string; init: RequestInit }> = [];
    const fetcher = vi.fn(async (url: string | URL | Request, init: RequestInit = {}) => {
      const value = String(url);
      requests.push({ url: value, init });
      if (value.includes('/dns_records?')) {
        const query = new URL(value).searchParams;
        const record = domain.expectedRecords.find((entry) => entry.type === query.get('type'))!;
        return Response.json({ success: true, result: [{ type: record.type, name: record.name, content: record.value }] });
      }
      if (value.endsWith('/email/routing') && init.method === 'GET') {
        return Response.json({ success: true, result: { enabled: false } });
      }
      if (value.endsWith('/email/routing/rules') && init.method === 'GET') {
        return Response.json({ success: true, result: [] });
      }
      if (value.endsWith('/email/routing/rules') && init.method === 'POST') {
        return Response.json({ success: true, result: { id: 'rule_1' } });
      }
      return Response.json({ success: true, result: {} });
    });
    const adapter = new CloudflareDomainAdapter({
      apiToken: 'secret', zoneId: 'zone_1', zoneName: 'mail.example.com', workerName: 'mailfn', fetch: fetcher,
    });

    await expect(adapter.verifyDns(domain)).resolves.toEqual({ verified: true, diagnostics: [] });
    await expect(adapter.createRouting(domain)).resolves.toEqual({ routingRuleId: 'rule_1' });
    await adapter.disableRouting({ ...domain, routingRuleId: 'rule_1' });

    expect(requests.every((entry) => new Headers(entry.init.headers).get('Authorization') === 'Bearer secret')).toBe(true);
    const createRule = requests.find((entry) => entry.url.endsWith('/email/routing/rules') && entry.init.method === 'POST')!;
    expect(JSON.parse(String(createRule.init.body))).toMatchObject({
      actions: [{ type: 'worker', value: ['mailfn'] }],
    });
    expect(requests.some((entry) => entry.url.endsWith('/email/routing/enable') && entry.init.method === 'POST')).toBe(true);
    expect(requests.some((entry) => entry.url.endsWith('/email/routing/dns') && entry.init.method === 'GET')).toBe(true);
    expect(requests.at(-1)).toMatchObject({
      url: 'https://api.cloudflare.com/client/v4/zones/zone_1/email/routing/rules/rule_1',
      init: { method: 'DELETE' },
    });
  });

  it('reports missing records without mutating routing', async () => {
    const fetcher = vi.fn(async () => Response.json({ success: true, result: [] }));
    const adapter = new CloudflareDomainAdapter({
      apiToken: 'secret', zoneId: 'zone_1', zoneName: 'mail.example.com', workerName: 'mailfn', fetch: fetcher,
    });
    await expect(adapter.verifyDns(domain)).resolves.toEqual({
      verified: false,
      diagnostics: ['Missing TXT _mailfn.mail.example.com', 'Missing MX mail.example.com'],
    });
    expect(fetcher).toHaveBeenCalledTimes(3);
    expect(fetcher.mock.calls.every((call) => call[1]?.method === 'GET')).toBe(true);
  });

  it('rejects a domain that is not the exact authorized Cloudflare zone', async () => {
    const fetcher = vi.fn();
    const adapter = new CloudflareDomainAdapter({
      apiToken: 'secret', zoneId: 'zone_1', zoneName: 'example.com', workerName: 'mailfn', fetch: fetcher,
    });
    await expect(adapter.verifyDns(domain)).rejects.toThrow('MAILFN_CLOUDFLARE_ZONE_MISMATCH');
    expect(fetcher).not.toHaveBeenCalled();
  });
});

