import {
  MAILFN_API_VERSION,
  MailFn,
  MailFnError,
  type Actor,
  type CreateInboxInput,
  type CreateProjectInput,
  type MailFnScope,
  type MessageFilter,
  type UpdateInboxInput,
  type WaitForMessageInput,
} from '@mailfn/core';

export interface MailFnHttpHandlerConfig {
  mailfn: MailFn;
  adminToken?: string;
  adminProjectId?: string;
  corsOrigins?: string[];
}

export function createMailFnHttpHandler(config: MailFnHttpHandlerConfig): (request: Request) => Promise<Response> {
  const route = createMailFnRouteHandler(config);
  return async (request) => cors(await route(request), request, config.corsOrigins);
}

function createMailFnRouteHandler(config: MailFnHttpHandlerConfig): (request: Request) => Promise<Response> {
  return async (request) => {
    const requestId = request.headers.get('x-request-id') ?? `req_${crypto.randomUUID().replaceAll('-', '')}`;
    try {
      if (request.method === 'OPTIONS') return cors(new Response(null, { status: 204 }), request, config.corsOrigins);
      const url = new URL(request.url);
      const path = url.pathname.replace(/\/+$/, '') || '/';
      if (path === '/health' && request.method === 'GET') return json({ status: 'ok', version: MAILFN_API_VERSION }, requestId);
      if (path === '/v1/admin/projects' && request.method === 'POST') {
        requireAdmin(request, config.adminToken);
        return json(await config.mailfn.bootstrapProject(await body<CreateProjectInput>(request)), requestId, 201);
      }
      const actor = await authenticate(request, config);

      if (path === '/v1/inboxes' && request.method === 'POST') {
        const input = await body<Omit<CreateInboxInput, 'projectId'>>(request);
        return json(await config.mailfn.createInbox(actor, { ...input, projectId: actor.projectId }), requestId, 201);
      }
      if (path === '/v1/inboxes' && request.method === 'GET') return json(await config.mailfn.listInboxes(actor), requestId);

      let match = path.match(/^\/v1\/inboxes\/([^/]+)$/);
      if (match) {
        const inboxId = decode(match[1]);
        if (request.method === 'GET') return json(await config.mailfn.getInbox(actor, inboxId), requestId);
        if (request.method === 'PATCH') return json(await config.mailfn.updateInbox(actor, inboxId, await body<UpdateInboxInput>(request)), requestId);
        if (request.method === 'DELETE') return json(await config.mailfn.deleteInbox(actor, inboxId), requestId);
      }

      match = path.match(/^\/v1\/inboxes\/([^/]+)\/tokens$/);
      if (match && request.method === 'POST') {
        const inboxId = decode(match[1]);
        const input = await body<{ permissions: MailFnScope[]; expiresAt?: string }>(request);
        return json(await config.mailfn.createCredential(actor, {
          projectId: actor.projectId,
          inboxId,
          permissions: input.permissions,
          expiresAt: input.expiresAt,
        }), requestId, 201);
      }
      match = path.match(/^\/v1\/inboxes\/([^/]+)\/tokens\/([^/]+)$/);
      if (match && request.method === 'DELETE') {
        await config.mailfn.getInbox(actor, decode(match[1]));
        return json(await config.mailfn.revokeCredential(actor, decode(match[2])), requestId);
      }

      match = path.match(/^\/v1\/inboxes\/([^/]+)\/messages$/);
      if (match && request.method === 'GET') {
        const inboxId = decode(match[1]);
        return json(await config.mailfn.listMessages(actor, {
          inboxId,
          ...messageFilter(url.searchParams),
          cursor: url.searchParams.get('cursor') ?? undefined,
          limit: numberParam(url.searchParams, 'limit'),
        }), requestId);
      }

      match = path.match(/^\/v1\/inboxes\/([^/]+)\/messages\/wait$/);
      if (match && request.method === 'POST') {
        const inboxId = decode(match[1]);
        const input = await body<Omit<WaitForMessageInput, 'projectId' | 'inboxId' | 'signal'>>(request);
        return json(await config.mailfn.waitForMessages(actor, { ...input, inboxId, signal: request.signal }), requestId);
      }

      match = path.match(/^\/v1\/inboxes\/([^/]+)\/messages\/search$/);
      if (match && request.method === 'GET') {
        return json(await config.mailfn.searchMessages(actor, {
          inboxId: decode(match[1]),
          query: url.searchParams.get('query') ?? '',
          cursor: url.searchParams.get('cursor') ?? undefined,
          limit: numberParam(url.searchParams, 'limit'),
          receivedAfter: url.searchParams.get('receivedAfter') ?? undefined,
          receivedBefore: url.searchParams.get('receivedBefore') ?? undefined,
        }), requestId);
      }

      match = path.match(/^\/v1\/inboxes\/([^/]+)\/messages\/([^/]+)$/);
      if (match && request.method === 'GET') {
        return json(await config.mailfn.getMessage(actor, decode(match[1]), decode(match[2])), requestId);
      }
      match = path.match(/^\/v1\/inboxes\/([^/]+)\/messages\/([^/]+)\/raw$/);
      if (match && request.method === 'GET') {
        const data = await config.mailfn.getRawMessage(actor, decode(match[1]), decode(match[2]));
        return binary(data, 'message/rfc822', requestId);
      }
      match = path.match(/^\/v1\/inboxes\/([^/]+)\/messages\/([^/]+)\/attachments$/);
      if (match && request.method === 'GET') {
        return json(await config.mailfn.listAttachments(actor, decode(match[1]), decode(match[2])), requestId);
      }
      match = path.match(/^\/v1\/inboxes\/([^/]+)\/messages\/([^/]+)\/attachments\/([^/]+)$/);
      if (match && request.method === 'GET') {
        const result = await config.mailfn.getAttachment(actor, decode(match[1]), decode(match[2]), decode(match[3]));
        return binary(result.data, result.attachment.contentType, requestId, result.attachment.filename);
      }
      match = path.match(/^\/v1\/inboxes\/([^/]+)\/messages\/([^/]+)\/extract$/);
      if (match && request.method === 'POST') {
        const input = await body<{ type: 'otp' | 'verification_link' }>(request);
        return json(await config.mailfn.extractVerification(actor, decode(match[1]), decode(match[2]), input.type), requestId);
      }
      match = path.match(/^\/v1\/inboxes\/([^/]+)\/messages\/([^/]+)\/labels$/);
      if (match && request.method === 'PUT') {
        const input = await body<{ labels: string[] }>(request);
