        const snapshot = await config.mailfn.getOperationalSnapshot(actor);
        return json({ snapshot, alerts: config.mailfn.evaluateOperationalAlerts(snapshot) }, requestId);
      }
      if (path === '/v1/billing/usage' && request.method === 'GET') {
        return json(await config.mailfn.getUsage(actor, url.searchParams.get('period') ?? undefined), requestId);
      }
      if (path === '/v1/abuse' && request.method === 'POST') {
        return json(await config.mailfn.reportAbuse(actor, await body(request)), requestId, 201);
