import {
  createMailFnCloudflareHandlers,
  type MailFnCloudflareEnv,
} from '@mailfn/cloudflare';

export interface RouterMailEnv extends MailFnCloudflareEnv {
  ROUTER_MAIL_FROM: string;
}

export function createRouterMailWorker() {
  const handlers = createMailFnCloudflareHandlers();
  return {
    fetch: (request: Request, env: RouterMailEnv) => handlers.fetch(request, env),
    email: handlers.email,
    queue: handlers.queue,
    scheduled: handlers.scheduled,
  };
}
import { MailFnClient, type MailFnClientConfig } from '@mailfn/client';
import {
  MailFn,
  MemoryMailFnObjectStore,
  MemoryMailFnStore,
  noOpSecretProtector,
  type MailFnSendAdapter,
} from '@mailfn/core';

export function createStandaloneMailbox(sendAdapter?: MailFnSendAdapter): MailFn {
  return new MailFn({
    store: new MemoryMailFnStore(),
    objects: new MemoryMailFnObjectStore(),
    secretProtector: noOpSecretProtector,
    defaultDomain: 'mail.example.test',
    sendAdapter,
  });
}

export function createMailboxClient(config: MailFnClientConfig): MailFnClient {
  const client = new MailFnClient(config);
  void client.listInboxes;
  void client.listAttachments;
  void client.createReplyDraft;
  void client.exportCompliance;
  return client;
}
# MailFn consumer contracts

These compile-only fixtures keep the reusable boundary honest:

- `router-cloudflare.ts` models Router's Cloudflare Worker service shape and composes MailFn with SendFn without importing MailFn internals.
- `framework-neutral.ts` proves an unrelated application can use the provider-neutral in-memory core and typed HTTP client.

The MailFn release gate copies both fixtures into the clean tarball-install project and typechecks them there. They are validation inputs, not published packages and not production deployment configuration.

