import { MailFnError } from './errors.js';

const LOCAL_PART_PATTERN = /^[a-z0-9](?:[a-z0-9._-]{0,62}[a-z0-9])?$/;
const DOMAIN_PATTERN = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;

export function normalizeAddress(value: string): string {
  const normalized = value.trim().toLowerCase();
  const at = normalized.lastIndexOf('@');
  if (at <= 0 || at === normalized.length - 1) {
    throw invalidAddress();
  }
  const localPart = normalized.slice(0, at);
  const domain = normalized.slice(at + 1);
  if (!LOCAL_PART_PATTERN.test(localPart) || !DOMAIN_PATTERN.test(domain)) {
    throw invalidAddress();
  }
  return `${localPart}@${domain}`;
}

export function normalizeDomain(value: string): string {
  const normalized = value.trim().toLowerCase().replace(/\.$/, '');
  if (!DOMAIN_PATTERN.test(normalized)) {
    throw new MailFnError({
      code: 'MAILFN_VALIDATION_FAILED',
      message: 'Invalid mail domain',
      status: 400,
    });
  }
  return normalized;
}

export function normalizeLocalPart(value: string): string {
  const normalized = value.trim().toLowerCase();
  if (!LOCAL_PART_PATTERN.test(normalized)) {
    throw new MailFnError({
      code: 'MAILFN_VALIDATION_FAILED',
      message: 'Invalid inbox local part',
      status: 400,
    });
  }
  return normalized;
}

export function addressDomain(address: string): string {
  return normalizeAddress(address).split('@')[1] as string;
}

function invalidAddress(): MailFnError {
  return new MailFnError({
    code: 'MAILFN_VALIDATION_FAILED',
    message: 'Invalid email address',
    status: 400,
  });
}
import type { ExtractedVerification, Message } from './types.js';

const OTP_PATTERNS = [
  /(?:verification|security|login|one[- ]time|auth(?:entication)?|confirm(?:ation)?)\s*(?:code|pin|otp)?\s*(?:is|:|-)?\s*([0-9]{4,10})/i,
  /\b([0-9]{6})\b/,
];

const LINK_PATTERN = /https?:\/\/[^\s<>"']+/gi;
const VERIFY_TERMS = /verify|verification|confirm|activate|magic|login|reset|recover/i;

export function extractOtp(message: Message): ExtractedVerification | null {
  for (const [field, value] of verificationFields(message)) {
    const plain = stripMarkup(value);
    for (const pattern of OTP_PATTERNS) {
      const match = pattern.exec(plain);
      if (match?.[1]) {
        return source(message, 'otp', match[1], field);
      }
    }
  }
  return null;
}

export function extractVerificationLink(message: Message): ExtractedVerification | null {
  const candidates: Array<{ value: string; field: 'subject' | 'text' | 'html'; score: number }> = [];
  for (const [field, value] of verificationFields(message)) {
    const matches = value.match(LINK_PATTERN) ?? [];
    for (const raw of matches) {
      const normalized = raw.replace(/&amp;/g, '&').replace(/[).,;]+$/, '');
      let parsed: URL;
      try {
        parsed = new URL(normalized);
      } catch {
        continue;
      }
      if (!['http:', 'https:'].includes(parsed.protocol)) continue;
      const score =
        (VERIFY_TERMS.test(parsed.pathname) ? 4 : 0) +
        (VERIFY_TERMS.test(parsed.search) ? 3 : 0) +
        (parsed.searchParams.has('token') || parsed.searchParams.has('code') ? 2 : 0) +
        (field === 'html' ? 1 : 0);
      candidates.push({ value: parsed.toString(), field, score });
    }
  }
  candidates.sort((left, right) => right.score - left.score || left.value.localeCompare(right.value));
  const selected = candidates[0];
  return selected ? source(message, 'verification_link', selected.value, selected.field) : null;
}

function verificationFields(message: Message): Array<['subject' | 'text' | 'html', string]> {
  return [
    ['subject', message.subject],
    ['text', message.textBody ?? ''],
    ['html', message.htmlBody ?? ''],
  ];
}

function stripMarkup(value: string): string {
  return value.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ');
}

function source(
  message: Message,
  type: ExtractedVerification['type'],
  value: string,
  matchedField: ExtractedVerification['matchedField'],
): ExtractedVerification {
  return {
    type,
    value,
    sourceMessageId: message.id,
    receivedAt: message.receivedAt,
    matchedField,
  };
}
import type {
  MailFnClock,
  MailFnIdGenerator,
  MailFnSecretProtector,
  MailFnTokenCodec,
} from './contracts.js';

const encoder = new TextEncoder();

function bytesToHex(bytes: Uint8Array): string {
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
}

function randomHex(bytes: number): string {
  const value = new Uint8Array(bytes);
  globalThis.crypto.getRandomValues(value);
  return bytesToHex(value);
}

export const systemClock: MailFnClock = {
  now: () => new Date(),
  sleep(ms, signal) {
    if (signal?.aborted) return Promise.reject(new DOMException('Aborted', 'AbortError'));
    return new Promise<void>((resolve, reject) => {
      const timer = setTimeout(resolve, Math.max(0, ms));
      signal?.addEventListener(
        'abort',
        () => {
          clearTimeout(timer);
          reject(new DOMException('Aborted', 'AbortError'));
        },
        { once: true },
      );
    });
  },
};

export const defaultIdGenerator: MailFnIdGenerator = {
  generate(prefix) {
    return `${prefix}_${globalThis.crypto.randomUUID().replaceAll('-', '')}`;
  },
};

export const sha256TokenCodec: MailFnTokenCodec = {
  async create(credentialId) {
    const secret = randomHex(32);
    const token = `mfn_${credentialId}_${secret}`;
    return {
      token,
      hash: await this.hash(token),
      prefix: token.slice(0, Math.min(24, token.length)),
    };
  },
  async hash(token) {
    const digest = await globalThis.crypto.subtle.digest('SHA-256', encoder.encode(token));
    return bytesToHex(new Uint8Array(digest));
  },
  equals(left, right) {
    if (left.length !== right.length) return false;
    let difference = 0;
    for (let index = 0; index < left.length; index += 1) {
      difference |= left.charCodeAt(index) ^ right.charCodeAt(index);
    }
    return difference === 0;
  },
};

export function createAesGcmSecretProtector(key: CryptoKey): MailFnSecretProtector {
  return {
    async protect(secret) {
      const iv = globalThis.crypto.getRandomValues(new Uint8Array(12));
      const ciphertext = await globalThis.crypto.subtle.encrypt(
        { name: 'AES-GCM', iv },
        key,
        encoder.encode(secret),
      );
      return `${bytesToHex(iv)}.${bytesToHex(new Uint8Array(ciphertext))}`;
    },
    async reveal(value) {
      const [ivHex, ciphertextHex] = value.split('.');
      if (!ivHex || !ciphertextHex) throw new Error('MAILFN_SECRET_CIPHERTEXT_INVALID');
      const fromHex = (hex: string) => Uint8Array.from(hex.match(/.{2}/g) ?? [], (part) => Number.parseInt(part, 16));
      const plaintext = await globalThis.crypto.subtle.decrypt(
        { name: 'AES-GCM', iv: fromHex(ivHex) },
        key,
        fromHex(ciphertextHex),
      );
      return new TextDecoder().decode(plaintext);
    },
  };
}

export const noOpSecretProtector: MailFnSecretProtector = {
  protect: async (secret) => secret,
  reveal: async (secret) => secret,
};
