+    if (!actor.scopes.includes('project:admin')) {
+      assertMailFn(input.permissions.every((scope) => actor.scopes.includes(scope)), {
+        code: 'MAILFN_FORBIDDEN',
+        message: 'Delegated credentials cannot exceed the actor scopes',
